const source = $json || {};

const asArray = (value) => Array.isArray(value) ? value : [];
const trimText = (value, max = 600) => String(value ?? '').trim().slice(0, max);

const actividad = asArray(source.actividad_reciente)
  .slice(0, 8)
  .map((item) => ({
    rol: trimText(item?.rol, 40),
    texto: trimText(item?.texto, 600),
    created_at: item?.created_at || null,
  }));

const contexto = {
  usuario_id: source.usuario_id,
  briefing_date: source.briefing_date,
  nombre: trimText(source.nombre, 120) || 'Usuario',
  tipo_usuario: trimText(source.tipo_usuario, 80) || 'indefinido',
  rubro: trimText(source.rubro, 160),
  etapa_actual: trimText(source.etapa_actual, 120),
  score_actual: Number(source.score_actual || 0),
  prioridad_actual: trimText(source.prioridad_actual, 500),
  resumen_actual: trimText(source.resumen_actual, 900),
  objetivos: asArray(source.objetivos).slice(0, 6),
  tareas: asArray(source.tareas).slice(0, 8),
  seguimientos: asArray(source.seguimientos).slice(0, 6),
  acciones_recientes: asArray(source.acciones_recientes).slice(0, 8),
  memorias_relevantes: asArray(source.memorias_relevantes).slice(0, 10),
  diagnosticos_recientes: asArray(source.diagnosticos_recientes).slice(0, 5),
  actividad_reciente: actividad,
  metricas: source.metricas && typeof source.metricas === 'object' ? source.metricas : {},
};

return {
  json: {
    ...source,
    nombre: contexto.nombre,
    tipo_usuario: contexto.tipo_usuario,
    contexto_briefing: JSON.stringify(contexto),
    prompt_version: 'briefing-prompt-v5',
    model_version: 'gpt-5.4-mini',
  },
};

const response = $json || {};
const source = $('02 F5 Preparar contexto').item.json || {};

const collectText = (value) => {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(collectText).filter(Boolean).join('\n');
  if (!value || typeof value !== 'object') return '';
  if (typeof value.text === 'string') return value.text;
  if (typeof value.output_text === 'string') return value.output_text;
  if (typeof value.content === 'string') return value.content;
  if (value.content) {
    const nested = collectText(value.content);
    if (nested) return nested;
  }
  if (value.message) {
    const nested = collectText(value.message);
    if (nested) return nested;
  }
  if (value.output) {
    const nested = collectText(value.output);
    if (nested) return nested;
  }
  if (value.response) {
    const nested = collectText(value.response);
    if (nested) return nested;
  }
  return '';
};

const raw = collectText(response).trim();
const cleaned = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');

if (start < 0 || end <= start) {
  throw new Error('EOS_BRIEFING_AI_JSON_MISSING');
}

let generated;
try {
  generated = JSON.parse(cleaned.slice(start, end + 1));
} catch (error) {
  throw new Error(`EOS_BRIEFING_AI_JSON_INVALID: ${error.message}`);
}

const text = (value, fallback = '', max = 1200) => {
  const normalized = String(value ?? '').trim();
  return (normalized || fallback).slice(0, max);
};
const list = (value, max = 3) => Array.isArray(value)
  ? value.slice(0, max).map((item) => ({
      titulo: text(item?.titulo, 'Pendiente', 220),
      descripcion: text(item?.descripcion, '', 700),
      ...(item?.nivel ? { nivel: ['bajo', 'medio', 'alto'].includes(String(item.nivel).toLowerCase()) ? String(item.nivel).toLowerCase() : 'medio' } : {}),
    }))
  : [];

const objetivos = Array.isArray(source.objetivos) ? source.objetivos : [];
const tareas = Array.isArray(source.tareas) ? source.tareas : [];
const nombre = text(source.nombre, 'Usuario', 120);
const fallbackPrincipal = text(
  objetivos[0]?.proximo_paso || objetivos[0]?.titulo || tareas[0]?.titulo,
  'Definir el resultado principal del dia.',
  600
);
const score = Math.max(0, Math.min(100, Number(source.score_actual || 0)));

const payload = {
  tipo_usuario: text(source.tipo_usuario, 'indefinido', 80),
  saludo: text(generated.saludo, `Buen dia, ${nombre}.`, 220),
  titulo_dia: text(generated.titulo_dia, fallbackPrincipal, 220),
  resumen: text(generated.resumen, 'EOS organizo las prioridades disponibles para sostener tu avance.', 1800),
  enfoque_dia: text(generated.enfoque_dia, fallbackPrincipal, 600),
  prioridad_1: text(generated.prioridad_1, fallbackPrincipal, 600),
  prioridad_2: text(generated.prioridad_2, tareas[0]?.titulo || 'Ordenar la informacion necesaria para ejecutar.', 600),
  prioridad_3: text(generated.prioridad_3, 'Registrar el avance real al cerrar el dia.', 600),
  recomendacion_principal: text(generated.recomendacion_principal, fallbackPrincipal, 1200),
  logros: list(generated.logros, 3),
  riesgos: list(generated.riesgos, 3),
  proximos_pasos: list(generated.proximos_pasos, 3),
  fuentes: {
    ...(source.metricas && typeof source.metricas === 'object' ? source.metricas : {}),
    generator: 'n8n-ai-v5',
    prompt_version: source.prompt_version || 'briefing-prompt-v5',
  },
  score,
};

return {
  json: {
    usuario_id: source.usuario_id,
    briefing_date: source.briefing_date,
    payload,
    model_version: source.model_version || 'gpt-5.4-mini',
    prompt_version: source.prompt_version || 'briefing-prompt-v5',
    execution_id: String($execution.id || ''),
  },
};
